const campaignItems=(e,s)=>e&&0!==e.length?"<ul class='list-group'>"+$.map(e,e=>"<li class='list-group-item'>"+s(e)+"</li>").join("")+"</ul>":"<p class='text-muted'>No items.</p>",campaignResource=(e,s)=>"<div class='panel panel-default'><div class='panel-heading'><strong>"+escapeHtml(e)+"</strong></div><div class='panel-body'>"+s+"</div></div>",campaignDetails=e=>{const s=e.template||{},a=e.page||{},t=e.smtp||{},n=campaignItems(e.scenarios,e=>"<strong>"+escapeHtml(e.name)+"</strong> <span class='text-muted'>"+escapeHtml(e.template.name)+" / "+escapeHtml(e.page.name)+" / "+escapeHtml(e.smtp.name)+"</span>"),p=campaignItems(e.results,e=>"<strong>"+escapeHtml(e.email)+"</strong> <span class='text-muted'>"+escapeHtml(e.status)+"</span>"),m=campaignItems(e.timeline,e=>"<strong>"+escapeHtml(e.email)+"</strong> <span class='text-muted'>"+escapeHtml(e.message)+"</span>"),l=campaignItems(e.groups,e=>"<strong>"+escapeHtml(e.name)+"</strong>");return"<details><summary><strong>"+escapeHtml(e.name)+"</strong> <span class='label label-info'>"+escapeHtml(e.status)+"</span></summary><br><p><strong>URL:</strong> "+escapeHtml(e.url||"")+"</p>"+campaignResource("Groups",l)+campaignResource("Email Template","<p><strong>"+escapeHtml(s.name||"[Deleted]")+"</strong> "+escapeHtml(s.subject||"")+"</p><pre>"+escapeHtml(s.text||"")+"</pre><pre>"+escapeHtml(s.html||"")+"</pre>")+campaignResource("Landing Page","<p><strong>"+escapeHtml(a.name||"[Deleted]")+"</strong></p><pre>"+escapeHtml(a.html||"")+"</pre>")+campaignResource("Sending Profile","<p><strong>"+escapeHtml(t.name||"[Deleted]")+"</strong> "+escapeHtml(t.host||"")+" / "+escapeHtml(t.from_address||"")+"</p>")+campaignResource("Phishing Scenarios",n)+campaignResource("Recipients and Results",p)+campaignResource("Event Timeline",m)+"</details>"};$(document).ready(()=>{api.userCampaigns.get().success(e=>{$("#loading").hide();const s=$.map(e,e=>{const s=e.campaigns&&e.campaigns.length>0?$.map(e.campaigns,campaignDetails).join("<hr>"):"<p class='text-muted'>No campaigns.</p>";return"<div class='panel panel-primary'><div class='panel-heading'><h3 class='panel-title'>"+escapeHtml(e.user.username)+" <small>"+escapeHtml(e.user.role.name)+"</small></h3></div><div class='panel-body'>"+s+"</div></div>"}).join("");$("#userCampaignWorkspaces").html(s).show()}).error(e=>{$("#loading").hide(),errorFlash(e.responseJSON?e.responseJSON.message:"Error loading user campaigns")})});